  for (const f of files) {
    try {
      const data = JSON.parse(fs.readFileSync(path.join(FASTOPS, f), 'utf8'));
      data._file = f;
      artifacts.push(data);
    } catch { /* skip corrupt */ }
  }
  return artifacts;
}

